const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
let current='overview',paused=false,dirty=false,refreshing=false;
const titles={overview:'状态 / 澜总览',docker:'服务 / Dockerman JS',settings:'系统 / 设置'};
function indicator(nav){const active=nav.querySelector('[aria-current="page"]'),track=nav.querySelector('.pill-indicator');if(!active||!track)return;track.style.width=active.offsetWidth+'px';track.style.transform=`translateX(${active.offsetLeft}px)`;}
function menu(open){$('#sidebar').classList.toggle('open',open);$('.scrim').hidden=!open;$('#menu').setAttribute('aria-expanded',open);$('.workspace').inert=open; document.body.style.overflow=open?'hidden':'';if(open) $('.close-menu').focus();else $('#menu').focus();}
$$('[data-page]').forEach(b=>b.addEventListener('click',()=>{if(dirty&&b.dataset.page!==current){$('#dirty').textContent='请先保存或撤销更改，再切换页面。';$('#dirty').focus();return;}current=b.dataset.page;$$('.page').forEach(p=>p.hidden=p.id!==current);$$('aside [data-page]').forEach(x=>x.removeAttribute('aria-current'));const selected=$(`aside [data-page="${current}"]`);if(selected) selected.setAttribute('aria-current','page');$('#breadcrumb').textContent=titles[current];if($('#sidebar').classList.contains('open'))menu(false);if(current==='docker')renderDocker();requestAnimationFrame(()=>$$('.pills').forEach(indicator));}));
$$('.group[aria-controls]').forEach(b=>b.addEventListener('click',()=>{const open=b.getAttribute('aria-expanded')!=='true';b.setAttribute('aria-expanded',open);$('#'+b.getAttribute('aria-controls')).classList.toggle('collapsed',!open);}));
$('#menu').onclick=()=>menu(true);$('.close-menu').onclick=()=>menu(false);$('.scrim').onclick=()=>menu(false);document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#sidebar').classList.contains('open'))menu(false)});
const mq=matchMedia('(prefers-color-scheme:light)');function theme(){document.documentElement.classList.toggle('light',$('#appearance').value==='light'||($('#appearance').value==='auto'&&mq.matches));}$('#appearance').onchange=theme;mq.addEventListener('change',theme);
$('#motion').onclick=()=>{const off=document.documentElement.classList.toggle('motion-off');$('#motion').textContent='动效：'+(off?'关':'开');$('#motion').setAttribute('aria-pressed',!off);};
$('#pause').onclick=()=>{paused=!paused;$('#pause').textContent=paused?'继续':'暂停';$('#pause').setAttribute('aria-pressed',paused);$('#freshness').textContent=paused?'已暂停自动更新 · 演示':'演示数据 · 每 5 秒采样';};
$('#refresh').onclick=()=>{if(refreshing)return;refreshing=true;const b=$('#refresh');b.disabled=true;b.classList.add('busy');b.querySelector('span').textContent='更新中';$('#freshness').textContent='正在刷新演示数据…';setTimeout(()=>{refreshing=false;b.disabled=false;b.classList.remove('busy');b.querySelector('span').textContent='刷新';if($('#scenario').value==='error'){ $('#notice').hidden=false;$('#notice').textContent='刷新失败，已保留上次数据。请检查连接后重试。（演示）';$('#freshness').textContent='更新失败 · 当前显示上次数据';}else{$('#notice').hidden=true;$('#freshness').textContent=paused?'已更新演示数据 · 自动更新仍暂停':'刚刚更新 · 演示数据';}},700);};
$('#scenario').onchange=()=>{const s=$('#scenario').value;$('.gap').hidden=s!=='gap';$('.chart').classList.toggle('gap-mode',s==='gap');$('#devices').hidden=s==='empty';$('#devices-empty').hidden=s!=='empty';$('#notice').hidden=s!=='error';$('#notice').textContent='刷新失败，已保留上次数据。请检查连接后重试。（演示）';$('#freshness').textContent=s==='error'?'数据已过期 · 上次更新 2 分钟前':'演示数据 · 每 5 秒采样';if(current==='docker')renderDocker();};
$('#range').onchange=()=>{const longer=$('#range').selectedIndex===1;$('.axis span:first-child').textContent=longer?'22:28':'22:38';$('.axis span:nth-child(2)').textContent=longer?'演示 · 15 分钟窗口':'量程 3.1 Mbit/s';};
let dockerTab='概览';function renderDocker(){const t=dockerTab;$('#docker-title').textContent='Docker '+t;$('#docker-description').textContent=t==='概览'?'服务状态与资源使用，一目了然。':'查看与管理 Docker '+t+'。原型仅演示视觉与交互。';let body='';if(t==='概览')body='<article class="panel"><div class="panel-head"><h2>Docker 服务</h2><span class="status">运行中</span></div><dl><div><dt>版本</dt><dd>27.3.1 · 演示</dd></div><div><dt>数据目录</dt><dd>/opt/docker</dd></div></dl><div class="docker-summary"><div><strong>3</strong><span>容器 · 2 个运行中</span></div><div><strong>5</strong><span>镜像</span></div><div><strong>2</strong><span>网络</span></div></div><p class="secondary-text">通过上方胶囊导航查看配置、容器和镜像。</p></article>';else if(t==='容器')body='<article class="panel"><div class="panel-head"><h2>容器列表</h2><span class="secondary-text">演示数据</span></div>'+($('#scenario').value==='empty'?'<p class="empty">还没有容器。正式页面在此保留插件原有创建入口。</p>':'<div class="table-wrap"><table><thead><tr><th>名称</th><th>镜像</th><th>状态</th></tr></thead><tbody><tr><td>home-assistant</td><td>homeassistant:stable</td><td class="status">运行中</td></tr><tr><td>adguard</td><td>adguardhome:latest</td><td class="status">运行中</td></tr><tr><td>alpine-test</td><td>alpine:3.20</td><td>已停止</td></tr></tbody></table></div>')+'</article>';else body='<article class="panel"><h2>'+t+'页面的统一样式</h2><p class="empty">此页用于检查胶囊切换、标题间距与焦点。具体内容沿用插件原有功能。</p></article>';$('#docker-content').innerHTML=body;$('#docker-content').classList.remove('swapping');void $('#docker-content').offsetWidth;$('#docker-content').classList.add('swapping');}
$$('.pills').forEach(nav=>{const buttons=[...nav.querySelectorAll('button')];buttons.forEach(b=>b.onclick=()=>{if(nav.closest('#settings')&&dirty){$('#dirty').textContent='请先保存或撤销当前设置，再切换。';return;}buttons.forEach(x=>x.removeAttribute('aria-current'));b.setAttribute('aria-current','page');indicator(nav);b.scrollIntoView({block:'nearest',inline:'nearest',behavior:document.documentElement.classList.contains('motion-off')?'instant':'smooth'});if(b.dataset.interface){$('#dhcp-pane').hidden=b.dataset.interface!=='DHCP 服务器';$('#interface-placeholder').hidden=b.dataset.interface==='DHCP 服务器';}else if(b.dataset.tab){dockerTab=b.dataset.tab;renderDocker();}else{$('#settings-title').textContent=b.dataset.setting;$('.form-panel').hidden=b.dataset.setting!=='基本设置';let placeholder=$('#settings-placeholder');if(!placeholder){placeholder=document.createElement('p');placeholder.id='settings-placeholder';placeholder.className='empty';placeholder.textContent='此页用于查看导航布局。正式页面沿用原有配置项。';$('#settings-form').append(placeholder);}placeholder.hidden=b.dataset.setting==='基本设置';}});nav.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;const index=buttons.indexOf(document.activeElement);if(index<0)return;e.preventDefault();const next=e.key==='Home'?0:e.key==='End'?buttons.length-1:(index+(e.key==='ArrowRight'?1:-1)+buttons.length)%buttons.length;buttons[next].focus();});});
function dirtyState(value){dirty=value;$('#save').disabled=!value;$('#dirty').textContent=value?'有未保存的更改':'没有未保存的更改';}$('#settings-form').oninput=()=>dirtyState(true);$('#settings-form').onreset=()=>{dirtyState(false);$('#hostname').removeAttribute('aria-invalid');$('#hostname-error').hidden=true;};$('#settings-form').onsubmit=e=>{e.preventDefault();const invalid=!$('#hostname').value.trim();$('#hostname-error').hidden=!invalid;$('#hostname').setAttribute('aria-invalid',invalid);if(invalid){$('#hostname').focus();return;}$('#save').disabled=true;$('#save').textContent='应用中';setTimeout(()=>{dirtyState(false);$('#dirty').textContent='演示配置已应用，未写入路由器';$('#save').textContent='保存并应用';},700);};
let deviceOpener;$$('[data-device]').forEach(b=>b.onclick=()=>{deviceOpener=b;$('#device-title').textContent=b.dataset.device;$('#detail').showModal();});function closeDetail(){const d=$('#detail');if(d.classList.contains('closing'))return;if(document.documentElement.classList.contains('motion-off')||matchMedia('(prefers-reduced-motion:reduce)').matches){d.close();deviceOpener?.focus();return;}d.classList.add('closing');setTimeout(()=>{d.close();d.classList.remove('closing');deviceOpener?.focus();},160);}$('#close-detail').onclick=closeDetail;$('#detail').addEventListener('cancel',e=>{e.preventDefault();closeDetail();});
window.addEventListener('resize',()=>$$('.pills').forEach(indicator));document.fonts.ready.then(()=>$$('.pills').forEach(indicator));renderDocker();theme();

$('#edit-interface').onclick=()=>{$('#interface-result').textContent='演示配置 · 不会写入路由器';$('#interface-dialog').showModal();requestAnimationFrame(()=>{$$('#interface-dialog .pills').forEach(indicator);$('#interface-dialog .pills [aria-current=page]').scrollIntoView({block:'nearest',inline:'nearest'});});};function closeInterface(){$('#interface-dialog').close();$('#edit-interface').focus();}$('#close-interface').onclick=closeInterface;$('#cancel-interface').onclick=closeInterface;$('#interface-dialog').addEventListener('cancel',e=>{e.preventDefault();closeInterface();});$('#apply-interface').onclick=()=>{$('#interface-result').textContent='已保存演示配置 · 未写入路由器';};$$('[data-dhcp]').forEach(b=>b.onclick=()=>{$$('[data-dhcp]').forEach(x=>x.removeAttribute('aria-current'));b.setAttribute('aria-current','page');$('#ipv6-fields').hidden=b.dataset.dhcp!=='IPv6 设置';$('#dhcp-placeholder').hidden=b.dataset.dhcp==='IPv6 设置';});

document.addEventListener('keydown',e=>{if(e.key==='Tab'&&$('#sidebar').classList.contains('open')){const items=[...$('#sidebar').querySelectorAll('button')].filter(x=>x.getBoundingClientRect().height>0&&getComputedStyle(x).visibility!=='hidden');const first=items[0],last=items[items.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});window.addEventListener('resize',()=>{if(innerWidth>820&&$('#sidebar').classList.contains('open'))menu(false);});
